import { formatUsd } from "@acme/ui/format";
import type { Cart } from "./types";

export function Summary({ cart }: { cart: Cart }) {
  return (
    <dl>
      <dt>Subtotal</dt><dd>{formatUsd(cart.subtotal)}</dd>
      {cart.coupon ? <><dt>Discount ({cart.coupon.code})</dt><dd>-{formatUsd(cart.coupon.amount)}</dd></> : null}
      <dt>Total</dt><dd>{formatUsd(cart.total)}</dd>
    </dl>
  );
}

