import { expect, test } from '@playwright/test';

test('top-up shows remaining balance', async ({ page }) => {
  await page.goto('/api/local-auth/login?name=free');
  await page.goto('/settings/subscription');
  await expect(page.getByText(/^Balance: /)).toHaveText('Balance: $19.47');
});

